window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-42701\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλομμειδής</h1><div class=\"entry-meta\"><span>DGP · ordem 495 na letra φ · nº geral 42701</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = φιλομειδής.</p></section></article>\n<article id=\"entry-dgp-42702\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλομουσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 496 na letra φ · nº geral 42702</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amor pela musas, i.e., pelas letras, pelas artes, pela música. 〈φιλόμουσος〉</p></section></article>\n<article id=\"entry-dgp-42703\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόμουσος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 497 na letra φ · nº geral 42703</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama as musas, i.e., as letras, as artes, a música 2 artístico. 〈φίλος, μοῦσα〉</p></section></article>\n<article id=\"entry-dgp-42704\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόμυρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 498 na letra φ · nº geral 42704</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gosta dos perfumes, das essências ♦ τὸ φιλόμυρον 2 amor pelos perfumes. 〈φίλος, μύρον〉</p></section></article>\n<article id=\"entry-dgp-42705\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλονεικέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 499 na letra φ · nº geral 42705</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gostar de querelas; gostar de vencer; ser competitivo; querelar por algo, ac. 2 brigar com, dat. 〈φιλόνεικος〉</p></section></article>\n<article id=\"entry-dgp-42706\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλονεικητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 500 na letra φ · nº geral 42706</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de φιλονεικέω.</p></section></article>\n<article id=\"entry-dgp-42707\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλονεικία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 501 na letra φ · nº geral 42707</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gosto pelas querelas; amor pelas disputas; temperamento litigioso 2 rivalidade; emulação; disputa: φιλονεικίαν ἐμβάλλειν τινί xen. despertar em alguém o desejo de rivalizar com outros. 〈φιλόνεικος〉</p></section></article>\n<article id=\"entry-dgp-42708\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόνεικος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 502 na letra φ · nº geral 42708</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama as disputas; que gosta de vencer; competitivo 2 de temperamento agressivo; briguento ♦ τὸ φιλόνεικον 3 = φιλονεικία. 〈φίλος, νεῖκος〉</p></section></article>\n<article id=\"entry-dgp-42709\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλονείκως</h1><div class=\"entry-meta\"><span>DGP · ordem 503 na letra φ · nº geral 42709</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com espírito belicoso 2 com emulação.</p></section></article>\n<article id=\"entry-dgp-42710\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόνικος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 504 na letra φ · nº geral 42710</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φιλόνεικος. 〈φίλος, νίκη〉</p></section></article>\n<article id=\"entry-dgp-42711\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόξεινος</h1><div class=\"entry-meta\"><span>DGP · ordem 505 na letra φ · nº geral 42711</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = φιλόξενος.</p></section></article>\n<article id=\"entry-dgp-42712\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοξενία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 506 na letra φ · nº geral 42712</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prática de hospitalidade. 〈φιλόξενος〉</p></section></article>\n<article id=\"entry-dgp-42713\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόξενος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 507 na letra φ · nº geral 42713</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que gosta de estrangeiros; que pratica a hospitalidade; hospitaleiro.</p></section></article>\n<article id=\"entry-dgp-42714\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοξένως</h1><div class=\"entry-meta\"><span>DGP · ordem 508 na letra φ · nº geral 42714</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo hospitaleiro.</p></section></article>\n<article id=\"entry-dgp-42715\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπαίγμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 509 na letra φ · nº geral 42715</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος que gosta de jogar; entusiasmado; alegre. 〈φίλος, παίζω〉</p></section></article>\n<article id=\"entry-dgp-42716\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπαίσμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 510 na letra φ · nº geral 42716</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φιλοπαίγμων.</p></section></article>\n<article id=\"entry-dgp-42717\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπαίστης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 511 na letra φ · nº geral 42717</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) = φιλοπαίγμων.</p></section></article>\n<article id=\"entry-dgp-42718\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπατρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 512 na letra φ · nº geral 42718</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amor por seu país. 〈φίλος, πάτριος〉</p></section></article>\n<article id=\"entry-dgp-42719\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόπατρις, ις, ι</h1><div class=\"entry-meta\"><span>DGP · ordem 513 na letra φ · nº geral 42719</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ιδος ac. sing. ιν (masc., fem.) 1 que ama seu país; patriota ♦ τὸ φιλόπατρι 2 amor pelo país; patriotismo. 〈φίλος, παρτρίς〉</p></section></article>\n<article id=\"entry-dgp-42720\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπάτωρ, ορος</h1><div class=\"entry-meta\"><span>DGP · ordem 514 na letra φ · nº geral 42720</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que ama o pai. 〈φίλος, πατήρ〉</p></section></article>\n<article id=\"entry-dgp-42721\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπενθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 515 na letra φ · nº geral 42721</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se compraz com a própria dor; que se entristece por gosto; que se abandona ao luto. 〈φίλος, πένθος〉</p></section></article>\n<article id=\"entry-dgp-42722\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπευθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 516 na letra φ · nº geral 42722</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gosta de saber ou de questionar; curioso ♦ τὸ φιλοπευθές 2 curiosidade. 〈φίλος, πυνθάνομαι〉</p></section></article>\n<article id=\"entry-dgp-42723\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπευστία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 517 na letra φ · nº geral 42723</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">desejo ou hábito de indagar; curiosidade. 〈φίλος, πυνθάνομαι〉</p></section></article>\n<article id=\"entry-dgp-42724\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπλουτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 518 na letra φ · nº geral 42724</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amar a riqueza. 〈φιλόπλουτος〉</p></section></article>\n<article id=\"entry-dgp-42725\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπλουτία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 519 na letra φ · nº geral 42725</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amor à riqueza. 〈φιλόπλουτος〉</p></section></article>\n<article id=\"entry-dgp-42726\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόπλουτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 520 na letra φ · nº geral 42726</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama as riquezas; ávido por riqueza ♦ τὸ φιλόπλουτον 2 amor à riqueza. 〈φίλος, πλοῦτος〉</p></section></article>\n<article id=\"entry-dgp-42727\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φιλοποίμην, μενος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 521 na letra φ · nº geral 42727</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Filopémen, n. de h. 〈φίλος, ποιμήν〉</p></section></article>\n<article id=\"entry-dgp-42728\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 522 na letra φ · nº geral 42728</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que faz amigos; que faz amizade ♦ τὸ φιλοποιόν 2 conciliação. 〈φίλος, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-42729\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπόλεμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 523 na letra φ · nº geral 42729</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gosta de guerra; belicoso ♦ τὸ φιλοπόλεμον 2 belicosidade. 〈φίλος, πόλεμος〉</p></section></article>\n<article id=\"entry-dgp-42730\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπολέμως</h1><div class=\"entry-meta\"><span>DGP · ordem 524 na letra φ · nº geral 42730</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com um caráter belicoso; de modo belicoso.</p></section></article>\n<article id=\"entry-dgp-42731\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόπολις, ις, ι</h1><div class=\"entry-meta\"><span>DGP · ordem 525 na letra φ · nº geral 42731</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ιδος 1 que ama a cidade; amigo da cidade 2 que ama sua cidade ou seu país; patriota ♦ τὸ φιλόπολι 3 patriotismo. 〈φίλος, πόλις〉</p></section></article>\n<article id=\"entry-dgp-42732\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπολίτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 526 na letra φ · nº geral 42732</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que ama os cidadãos ou seus concidadãos.</p></section></article>\n<article id=\"entry-dgp-42733\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 527 na letra φ · nº geral 42733</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 amar o trabalho; ser laborioso ♦ méd. 2 empenhar-se. 〈φιλόπονος〉</p></section></article>\n<article id=\"entry-dgp-42734\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπόνηρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 528 na letra φ · nº geral 42734</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que gosta de maldades ou de pessoas más. 〈φίλος, πονηρός〉</p></section></article>\n<article id=\"entry-dgp-42735\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπονία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 529 na letra φ · nº geral 42735</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amor pelo trabalho; gosto de fadiga; hábitos laboriosos. 〈φιλόπονος〉</p></section></article>\n<article id=\"entry-dgp-42736\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόπονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 530 na letra φ · nº geral 42736</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama o trabalho; laborioso; ativo; diligente em, πρός ou περί e ac. 2 que exige empenho; penoso. 〈φίλος, πόνος〉</p></section></article>\n<article id=\"entry-dgp-42737\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 531 na letra φ · nº geral 42737</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. laboriosamente; com empenho.</p></section></article>\n<article id=\"entry-dgp-42738\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοποσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 532 na letra φ · nº geral 42738</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amor pela bebida. 〈φιλοπότης〉</p></section></article>\n<article id=\"entry-dgp-42739\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπότης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 533 na letra φ · nº geral 42739</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que ama beber; grande bebedor; beberrão. 〈φίλος, πίνω〉</p></section></article>\n<article id=\"entry-dgp-42740\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπότις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 534 na letra φ · nº geral 42740</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) beberrona.</p></section></article>\n<article id=\"entry-dgp-42741\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπραγμοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 535 na letra φ · nº geral 42741</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 grande atividade; estilo de vida atarefado 2 mania de imiscuir-se nos assuntos alheios. 〈φιλοπράγμων〉</p></section></article>\n<article id=\"entry-dgp-42742\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπράγμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 536 na letra φ · nº geral 42742</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 ativo; atarefado 2 que gosta de imiscuir-se nos assuntos alheios; intrigante. 〈φίλος, πρᾶγμα〉</p></section></article>\n<article id=\"entry-dgp-42743\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπροσηγορία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 537 na letra φ · nº geral 42743</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 afabilidade 2 facilidade de discursar. 〈φιλοπροσήγορος〉</p></section></article>\n<article id=\"entry-dgp-42744\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπροσήγορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 538 na letra φ · nº geral 42744</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">afável; amável; cortês.</p></section></article>\n<article id=\"entry-dgp-42745\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · φ 539⟧</h1><div class=\"entry-meta\"><span>DGP · ordem 539 na letra φ · nº geral 42745</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φιλοπροσηνῶς(só superl. φιλοπροσηνέστατα) adv. com condescendência; com brandura; com cortesia. 〈φίλος, προσηνής〉</p></section></article>\n<article id=\"entry-dgp-42746\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπρωτεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 540 na letra φ · nº geral 42746</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. ambicionar o primeiro lugar; querer ser o primeiro. 〈φιλόπρωτος〉</p></section></article>\n<article id=\"entry-dgp-42747\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόπρωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 541 na letra φ · nº geral 42747</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gosta de ser o primeiro; que ambiciona o primeiro lugar ♦ τὸ φιλόπρωτον 2 desejo de ser o primeiro. 〈φίλος, πρῶτος〉</p></section></article>\n<article id=\"entry-dgp-42748\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοπτόλεμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 542 na letra φ · nº geral 42748</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φιλοπόλεμος.</p></section></article>\n<article id=\"entry-dgp-42749\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φίλορνις, ιθος</h1><div class=\"entry-meta\"><span>DGP · ordem 543 na letra φ · nº geral 42749</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 que ama os pássaros 2 amado por pássaros; frequentado pelos pássaros.</p></section></article>\n<article id=\"entry-dgp-42750\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόρρυθμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 544 na letra φ · nº geral 42750</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que gosta do ritmo, da cadência, da medida. 〈φίλος, ῥυθμός〉</p></section></article>\n<article id=\"entry-dgp-42751\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φίλος, η</h1><div class=\"entry-meta\"><span>DGP · ordem 545 na letra φ · nº geral 42751</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, poét., ος, ον (comp. φιλώτερος, φιλαίτερος, φίλτερος e φιλίων; superl. φίλτατος) 1 amigo; amado; querido; caro a alguém, dat.: voc. φίλος e φίλε com subst. masc. ou n., φίλε κασίγνητε hom. querido irmão, φίλε τέκνον hom. meu querido filho, φίλος ὦ Μενέλαε hom. ó amigo Menelau 2 que dá prazer; agradável a alguém, dat.: ἀπατάων μύθων τε κλοπίων, οἵ τοι φίλοι εἰσιν hom. palavras enganosas e astutas, que te são caras; φίλον ou φίλα ἐστί é agradável com inf. ou part., εἰ ὑμῖν φίλον plat. se isto vos agrada, ἐμοὶ οὐ φίλον ἐστὶ μεταλλῆσαι καὶ ἐρέσθαι hom. não me é agradável perguntar e responder, εἰ τόδ᾽ αὐτῷ φίλον κεκλημένῳ ésql. se lhe agrada ser chamado assim, αἰεί τοι τὰ κάκ᾽ ἐστὶ φίλα φρεσὶ μαντεύεσθαι hom. sempre é agradável a teu coração profetizar desgraças 3 que ama; amante de algo, gen.: φ. ἀληθείας plat. que ama a verdade 4 que testemunha amizade; benquerente; amigável com alguém, dat. ou gen.: φίλα δῶρα hom. afetuosos presentes, φίλα φρονέειν ou εἰδέναι τινί hom. demonstrar afeto por alguém, φίλα ποιεῖσθαι τινι her. testemunhar a amizade por alguém, acolher bem alguém 5 poét., partic. em Hom., φίλος equivale ao pron. poss. meu, teu, seu etc., ref. a seres ou objetos muito queridos: φίλον ἦτορ hom. meu coração, μητρὶ φίλῃ Ἀλθαίῃ χωόμενος κῆρ hom. irritado no seu coração contra sua mãe Alteia, φίλας περὶ χεῖρε βαλόντε ἀμφοτέρω hom. cerrando-nos ambos em nossos braços ♦ ὁ φίλος 6 amigo: ὁ ∆ιὸς φίλος ésql. amigo de Zeus, τοὺς ἐμαυτοῦ φίλους ésqn. meus amigos, τοὺς φίλους κτᾶσθαι tuc. cair nas boas graças dos amigos 7 aliado ♦ ἡ φίλη 8 amiga 9 mulher; esposa 10 mãe ♦ τὸ φίλον 11 objeto de afeição; ser querido; coisa querida; coisa amada, aceita, admitida ♦ τὰ φίλτατα 12 os objetos ou os seres mais queridos.</p></section></article>\n<article id=\"entry-dgp-42752\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόσιτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 546 na letra φ · nº geral 42752</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gosta de trigo. 2 que come bem. 〈φίλος, σῖτος〉</p></section></article>\n<article id=\"entry-dgp-42753\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοσκώμμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 547 na letra φ · nº geral 42753</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος que gosta de ridicularizar ou ironizar; zombador. 〈φίλος, σκώπτω〉</p></section></article>\n<article id=\"entry-dgp-42754\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοσοφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 548 na letra φ · nº geral 42754</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 esforçar-se para tornar-se instruído ou sábio 2 buscar o conhecimento, o saber 3 buscar ou cultivar uma ciência, uma arte 4 meditar; refletir; ocupar-se com algo de forma científica, metódica 5 dedicar-se com zelo a uma pesquisa ou a um estudo, ac. ou περί e gen. ou ac., ou ὑπέρ e gen.; aplicar-se ao estudo; estudar: φιλοσοφίαν φ. xen. dedicar-se ao estudo da filosofia 6 maquinar; tramar 7 cultivar a filosofia 8 ser filósofo 9 ensinar filosofia 10 crist. viver como filósofo, i.e., viver asceticamente 11 explicar; descrever 12 (pintura) representar conforme a verdade ♦ pas. 13 ser estudado cientificamente: τὰ φιλοσοφούμενα objetos de estudos filosóficos. 〈φιλόσοφος〉</p></section></article>\n<article id=\"entry-dgp-42755\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοσόφημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 549 na letra φ · nº geral 42755</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 objeto de estudo, de pesquisa, de meditação 2 Lóg. demonstração 3 estudo; tratado científico ou filosófico; pesquisa 4 princípio moral ou filosófico 5 invenção; meditação. 〈φιλοσοφέω〉</p></section></article>\n<article id=\"entry-dgp-42756\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοσοφητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 550 na letra φ · nº geral 42756</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de φιλοσοφέω.</p></section></article>\n<article id=\"entry-dgp-42757\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοσοφία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 551 na letra φ · nº geral 42757</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 amor pela ciência, pelo saber; busca do conhecimento 2 pesquisa; estudo sistemático ou científico, ou prática de uma arte ou de uma ciência 3 ciência; cultura intelectual 4 cultura metódica da eloqüência ou da dialética: ἡ περὶ τὰς ἔριδας φ. isócr. estudo científico da argumentação 5 procura da essência das coisas; estudo das coisas da natureza; busca da verdade; filosofia: ἡ περὶ τὰ ἀνθρώπινα φ. artt. a filosofia que concerne às coisas humanas 6 pl. sistemas filosóficos 7 crist. doutrina cristã; vida austera. 〈φιλόσοφος〉</p></section></article>\n<article id=\"entry-dgp-42758\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόσοφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 552 na letra φ · nº geral 42758</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama, pesquisa ou pratica uma arte ou uma ciência: φ. ἀνήρ xen. homem filósofo, φ. φύσις plat. natureza inclinada às coisas do espírito 2 que possui um caráter científico ou filosófico: φιλόσοφοι λόγοι plat. estudos filosóficos, ou isócr. discursos eruditos ♦ ὁ φιλόσοφος 3 aquele que ama o saber, o conhecimento, que ama as coisas do espírito; homem instruído; filósofo 4 professor de retórica 5 aquele que se ocupa dos assuntos da natureza, da busca da verdade: filósofo: φιλόσοφοι τὴν φύσιν ou φύσει plat. filósofos por natureza 6 o filósofo, ref. a Aristóteles 7 pessoa que leva vida austera 8 crist. asceta ♦ τὸ φιλόσοφον 9 conhecimentos filosóficos; filosofia 10 maneira de viver de um filósofo. 〈φίλος, σοφός〉</p></section></article>\n<article id=\"entry-dgp-42759\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοσόφως</h1><div class=\"entry-meta\"><span>DGP · ordem 553 na letra φ · nº geral 42759</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 sabiamente; sensatamente 2 filosoficamente; cientificamente.</p></section></article>\n<article id=\"entry-dgp-42760\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοστεφανέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 554 na letra φ · nº geral 42760</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amar, buscar ou disputar as coroas, i.e., a honra, a glória. 〈φιλοστέφανος〉</p></section></article>\n<article id=\"entry-dgp-42761\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοστέφανος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 555 na letra φ · nº geral 42761</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama as coroas.</p></section></article>\n<article id=\"entry-dgp-42762\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοστοργέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 556 na letra φ · nº geral 42762</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amar ternamente; querer com afeto, amar. 〈φιλόστοργος〉</p></section></article>\n<article id=\"entry-dgp-42763\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοστοργία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 557 na letra φ · nº geral 42763</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">viva afeição; ternura; amor; afeto. 〈φιλόστοργος〉</p></section></article>\n<article id=\"entry-dgp-42764\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόστοργος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 558 na letra φ · nº geral 42764</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama ternamente os seus; cheio de ternura pelos seus; devotado ♦ τὸ φιλόστοργον 2 ternura; afeto. 〈φίλος, στέργω〉</p></section></article>\n<article id=\"entry-dgp-42765\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοστόργως</h1><div class=\"entry-meta\"><span>DGP · ordem 559 na letra φ · nº geral 42765</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com ternura; afetuosamente.</p></section></article>\n<article id=\"entry-dgp-42766\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοστρατιώτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 560 na letra φ · nº geral 42766</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que gosta das coisas militares.</p></section></article>\n<article id=\"entry-dgp-42767\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόσυκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 561 na letra φ · nº geral 42767</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que gosta de figos. 〈φίλος, σῦκον〉</p></section></article>\n<article id=\"entry-dgp-42768\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοσυνήθης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 562 na letra φ · nº geral 42768</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que gosta de relacionar-se com os outros; que aprecia os relacionamentos; sociável, afável.</p></section></article>\n<article id=\"entry-dgp-42769\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοσύντομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 563 na letra φ · nº geral 42769</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que gosta de concisão.</p></section></article>\n<article id=\"entry-dgp-42770\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοσώματος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 564 na letra φ · nº geral 42770</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama o corpo; que toma cuidado consigo mesmo ♦ 2 τὸ φιλοσώματον 3 amor por si mesmo; cuidado tomado com o próprio corpo. 〈φίλος, σῶμα〉</p></section></article>\n<article id=\"entry-dgp-42771\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτεκνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 565 na letra φ · nº geral 42771</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amor pelos filhos. 〈φιλότεκνος〉</p></section></article>\n<article id=\"entry-dgp-42772\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλότεκνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 566 na letra φ · nº geral 42772</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama seus filhos ♦ τὸ φιλότεκνον 2 amor pelos filhos, pela prole. 〈φίλος, τέκνον〉</p></section></article>\n<article id=\"entry-dgp-42773\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτεχνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 567 na letra φ · nº geral 42773</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 amar ou praticar uma arte 2 fazer com arte; executar com habilidade algo, ac. 3 ocupar-se com gosto ou como conhecedor, de algo, περί e ac. 4 falar com gosto, como conhecedor de algo, ὑπέρ e gen., a alguém, πρός e ac. 5 maquinar; tramar algo, inf. 〈φιλότεχνος〉</p></section></article>\n<article id=\"entry-dgp-42774\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτέχνημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 568 na letra φ · nº geral 42774</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 obra de arte 2 trama bem feita. 〈φιλοτεχνέω〉</p></section></article>\n<article id=\"entry-dgp-42775\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλότεχνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 569 na letra φ · nº geral 42775</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama ou cultiva as artes 2 feito com arte; artístico; engenhoso (coisa) ♦ τὸ φιλότεχνον 3 amor ou gosto pela arte; habilidade. 〈φίλος, τέχνη〉</p></section></article>\n<article id=\"entry-dgp-42776\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτέχνως</h1><div class=\"entry-meta\"><span>DGP · ordem 570 na letra φ · nº geral 42776</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com gosto ou talento; com arte; artisticamente.</p></section></article>\n<article id=\"entry-dgp-42777\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 571 na letra φ · nº geral 42777</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 amizade; amor; afeição por alguém, gen.: ἐν φιλότητι διέτμαγεν ἀρθμήσαντε hom. separaram-se após amistoso acordo, φιλότητι plat. por amizade, φιλότητος παρά τινος τυχεῖν hom. obter uma boa acolhida de alguém, φιλότητα ἑλέσθαι hom. reconciliar-se, φιλότητα τιθέναι hom. criar amizade, aliança, φιλότητα τέμνειν hom. concluir um tratado de amizade, φιλότητα παρέχειν hom. demonstrar amizade, acolher com amizade, [κύλιξ] φέρεται φιλοτῆσιος teógn. uma taça é erguida em sinal de amizade 2 amor; relações íntimas: φ. κρυπταδίη hom. relações secretas, φιλότητι ὁμωθῆναι hom. ou μιγάζεσθαι hom., ἐν φιλότητι μίσγεσθαι hom. unir-se por relações íntimas 3 ente querido: ὦ φιλότης querido amor. 〈φίλος〉</p></section></article>\n<article id=\"entry-dgp-42778\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτήσιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 572 na letra φ · nº geral 42778</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 que concerne à amizade, ao amor ou aos prazeres do amor 2 que diz respeito à amizade; amistoso ♦ ἡ φιλοτησία 3 brinde que se faz a alguém: φιλοτησίαν ou φιλοτησίας προπίνειν dem. beber à saude de alguém, παρέχειν luc. oferecer um brinde, λαβεῖν ar. ou δέχεσθαι παρά e gen. luc. aceitar um brinde de alguém.</p></section></article>\n<article id=\"entry-dgp-42779\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτιμέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 573 na letra φ · nº geral 42779</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φιλοτιμήσομαι e φιλοτιμηθή­σομαι, aor. ἐφιλοτιμησάμην e ἐφιλοτιμήθην, perf. πεφιλοτίμημαι) 1 amar as honras; buscar as honras; ser ambicioso; procurar competir na obtenção de honras com alguém, πρός e ac., em rel. a algo, περί e gen. ou ac., ἀπό e gen., πρός e ac.: ὁ φιλοτιμούμενος lís. aquele que age por ambição ou rivalidade, εἰδώς με μάχιμον ὄντα φιλοτιμούμενος ar. ciente, competitivo que é, de que eu sou combativo, φιλοτιμούμενοι πρὸς ἀλλήλους plat. competindo entre si no apreço às honras 2 buscar; ambicionar; aspirar a algo, ac., ἐπί, ἐν e dat., ὑπέρ e gen.: φ. φιλοτιμίας plut. ter ambição de glória, φ. ὑπὲρ τῆς δόξης isócr. aspirar à glória 3 vangloriar-se de algo, ἐπι e dat., ἐν e dat., ὑπέρ e gen.: φιλοτιμεῖσθαι μηδ᾽ ἐφ᾽ ἐνὶ ἄλλῳ ἢ ἐπὶ χρημάτων κτήσει plat. vangloriar-se de outra coisa que não seja a posse de bens 4 trabalhar; esforçar-se; fazer todos os esforços: ἀεὶ ἔν γέ τι φιλοτιμούμενος xen. dando o máximo de si em alguma atividade, μὴ φιλοτιμοῦ ἐλέγχων plat. não te esforces em refutar, φιλοτιμουμένους ἐπιδείκνυσθαι πρὸς ἅπαν­τας ὅτι... plat. esforçando-se para mostrar a todos que 5 crist. ser generoso ou indulgente com alguém, πρός e ac. 〈φιλότιμος〉</p></section></article>\n<article id=\"entry-dgp-42780\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτίμημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 574 na letra φ · nº geral 42780</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o que se faz por amor próprio, por emulação 2 ostentação; prodigalidade 3 objeto de ambição, de ostentação. 〈φιλοτιμέομαι〉</p></section></article>\n<article id=\"entry-dgp-42781\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτιμητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 575 na letra φ · nº geral 42781</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de φιλοτιμέομαι.</p></section></article>\n<article id=\"entry-dgp-42782\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτιμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 576 na letra φ · nº geral 42782</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 amor ou desejo de honra, de glória; busca de honrarias 2 ambição; desejo; aspiração a algo, gen., ἐπί e dat., ὑπέρ e gen., περί ou πρός e ac.: φιλοτιμίαν φιλοτιμεῖσθαι luc. ter ambição, φιλοτιμιάν xen., φιλοτιμίᾳ dem., ὑπὸ φιλοτιμίας plat., διὰ φιλοτιμίαν plat., φιλοτιμίας ἕνεκα lís. por ambição 3 rivalidade; inveja: ἡ πρὸς ἀλλήλους φ. pol. a rivalidade mútua 4 pl. parcialidade: αἱ φιλοτιμίαι τῶν συγγραφέων pol. a parcialidade dos escritores 5 obstinação 6 ostentação ambiciosa 7 prodigalidade por ambição; munificência 8 pl. estratagemas ou propósitos ambiciosos 9 motivo de ambição; ponto de honra: φιλοτιμίαν ἔχειν τινί dem. ser motivo de honra para alguém, φιλοτιμίαν παραχωρεῖν τινι plut. ceder a honra a alguém por algo, φιλοτιμίαν παρέχειν τινί xen. proporcionar a alguém uma honra, ἀποστερεῖσθαι τῆς φιλοτιμίας ou τῶν ἰδίων φιλοτιμιῶν dem. ser privado de honras 10 ironia, comportamento digno de Filótimo. 〈φιλότιμος〉</p></section></article>\n<article id=\"entry-dgp-42783\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλότιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 577 na letra φ · nº geral 42783</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama ou busca honrarias, ambicioso 2 que aspira a; desejoso de, ἐπί e dat., περί e ac., ou inf.: φ. καλόν τι ποιεῖν xen. desejoso de realizar uma bela ação 3 generoso; pródigo em rel. a alguém, πρός ou περί e ac. 4 que rivaliza; que compete com alguém, πρός ac., por algo, περί e gen. ♦ τὸ φιλότιμον 5 ambição 6 objeto de ambição; coisa ambicionada. 〈φίλος, τιμή〉</p></section></article>\n<article id=\"entry-dgp-42784\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτίμως</h1><div class=\"entry-meta\"><span>DGP · ordem 578 na letra φ · nº geral 42784</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com ou por ambição; com desejo de distinguir-se; por desejo de honra ou glória 2 por rivalidade com alguém, πρός e ac. 3 com emulação; com zelo por algo, πρός e ac.</p></section></article>\n<article id=\"entry-dgp-42785\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτροφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 579 na letra φ · nº geral 42785</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gostar de alimentar, de sustentar. 〈φίλος, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-42786\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτύραννος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 580 na letra φ · nº geral 42786</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ama o tirano; favorável aos tiranos ♦ τὸ φιλοτύραννον 2 amor pela tirania.</p></section></article>\n<article id=\"entry-dgp-42787\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόφθονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 581 na letra φ · nº geral 42787</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 invejoso ♦ τὸ φιλόφθονον 2 inveja; ciúme. 〈φίλος, φθόνος〉</p></section></article>\n<article id=\"entry-dgp-42788\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόφιλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 582 na letra φ · nº geral 42788</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">afeiçoado aos amigos. 〈φίλος, φίλος〉</p></section></article>\n<article id=\"entry-dgp-42789\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοφρονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 583 na letra φ · nº geral 42789</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. 1 ter sentimentos de amizade ou de benevolência por alguém, ac., dat. ou περί, πρός e ac. 2 tratar ou acolher bem algo ou alguém, ac.: φ. ἀλλήλους xen. testemunhar bondade recíproca, φ. ἤθη κακά plat. acolher maus hábitos 3 prestar algum serviço, ac., a alguém, dat. 4 ser benévolo, gentil 5 (coisa) ser agradável a alguém, ac. 〈φιλόφρων〉</p></section></article>\n<article id=\"entry-dgp-42790\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοφρόνησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 584 na letra φ · nº geral 42790</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">disposição amigável ou gentil; gentileza; bondade. 〈φιλοφρονέομαι〉</p></section></article>\n<article id=\"entry-dgp-42791\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοφρόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 585 na letra φ · nº geral 42791</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com amizade; com gentileza.</p></section></article>\n<article id=\"entry-dgp-42792\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοφροσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 586 na letra φ · nº geral 42792</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 amizade ou gentileza; bondade, afabilidade por alguém, gen. πρός e ac., μετά e gen.; por algo, περί e ac.: διὰ φιλοφροσύνην plat., ὑπὸ ou μετὰ φιλοφροσύνης plut. com gentileza 2 bom humor; alegria 3 pl. sinais de afeição, de boas vindas. 〈φιλόφρων〉</p></section></article>\n<article id=\"entry-dgp-42793\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 587 na letra φ · nº geral 42793</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 gentil; bom; afável ♦ τὸ φιλόφρον 2 gentileza; bondade. 〈φίλος, φρήν〉</p></section></article>\n<article id=\"entry-dgp-42794\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόφωνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 588 na letra φ · nº geral 42794</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gosta de falar; loquaz ♦ τὸ φι­λόφωνον 2 loquacidade. 〈φίλος, φωνή〉</p></section></article>\n<article id=\"entry-dgp-42795\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόχορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 589 na letra φ · nº geral 42795</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama os coros, a dança. 〈φίλος, χορός〉</p></section></article>\n<article id=\"entry-dgp-42796\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοχρηματέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 590 na letra φ · nº geral 42796</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gostar de dinheiro. 〈φιλοχρήματος〉</p></section></article>\n<article id=\"entry-dgp-42797\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοχρηματία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 591 na letra φ · nº geral 42797</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amor pelo dinheiro. 〈φιλοχρήματος〉</p></section></article>\n<article id=\"entry-dgp-42798\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοχρήματος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 592 na letra φ · nº geral 42798</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gosta de dinheiro ♦ τὸ φιλοχρήματον 2 cupidez; ambição. 〈φίλος, χρῆμα〉</p></section></article>\n<article id=\"entry-dgp-42799\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοχρημάτως</h1><div class=\"entry-meta\"><span>DGP · ordem 593 na letra φ · nº geral 42799</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. por amor ao dinheiro; com ambição.</p></section></article>\n<article id=\"entry-dgp-42800\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόχρηστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 594 na letra φ · nº geral 42800</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ama o bem, a bondade, a virtude ou as pessoas de bem. 〈φίλος, χρηστός〉</p></section></article>\n";
